INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (37, 1, 'Ainuddin Nuruddin', 'Institute of Tropical Forestry and Forest Products (INTROP), Universiti Putra Malaysia', 'Universiti Putra Malaysia', '/storage/photos/ainuddin-nuruddin.png', 'Professor Dr Ahmad Ainuddin Nuruddin is an expert in forest sciences, specialising in forest fire management. His research has been pivotal in calibrating the Canadian Forest Fire Danger Rating System (FDRS) for application in Southeast Asia, enhancing the region’s ability to assess and mitigate fire risks. He authored and co-authored over 130 peer-reviewed articles and book chapters and presented at numerous national and international conferences. His work earned 2,565 citations and an h-index of 24.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (38, 1, 'Professor Dr Anjas Asmara @ Ab. Hadi Samsudin', 'Director, Institute of Tropical Agriculture and Food Security, Universiti Putra Malaysia', 'Universiti Putra Malaysia', '/storage/photos/professor-dr-anjas-asmara-at-ab-hadi-samsudin.jpeg', 'Professor Dr Anjas Asmara @ Ab. Hadi Samsudin is a recognised expert in livestock nutrition, specifically in gut molecular microbiology and minerals. He authored more than 120 publications, with 4,377 citations and an h-index of 37. His research on selenium-enriched microbial systems and alternative feed resources significantly contributed to improving nutrient efficiency and animal performance while reducing environmental impacts in livestock production.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (39, 1, 'Professor Ts Dr Chong Khim Phin', 'Faculty of Science and Natural Resources, University Malaysia Sabah', 'University Malaysia Sabah', '/storage/photos/professor-ts-dr-chong-khim-phin.png', 'Professor Ts Dr Chong Khim Phin is a plant pathologist specialising in the biological control of plant diseases. His research focuses on the biocontrol of Ganoderma to address fungal threats in oil palms and the development of bio-fertilisers to enhance soil health and crop productivity. He contributed his scientific and technical knowledge through the discovery and promotion of several biological control and early detection of oil palm-Ganoderma infection. He authored over 150 publications, including journal articles and widely cited books, achieving an h-index of 26 with more than 2,300 citations. He also secured several patents, some of which had been successfully commercialised and adopted in plantations.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (40, 1, 'Professor Ts Dr Hidayah Ariffin', 'Deputy Dean, Faculty of Biotechnology and Biomolecular Sciences, Universiti Putra Malaysia', 'Universiti Putra Malaysia', '/storage/photos/professor-ts-dr-hidayah-ariffin.jpeg', 'Professor Ts Dr Hidayah Ariffin is an expert in bioprocess engineering, specialising in biopolymers and nanocellulose. She is a recognised expert in the field, providing strategic advice to the academic community, government, and industry. Her publications recorded a citation count of 6,943 and an h-index of 47.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (41, 1, 'Professor Dr Jamal Hisham Hashim', 'Director, Provenue Corporation Sdn Bhd', 'Provenue Corporation Sdn Bhd', '/storage/photos/professor-dr-jamal-hisham-hashim.jpeg', 'Professor Dr Jamal Hisham Hashim is an expert in environmental health risk and impact assessment, as well as climate change and health. He is well-versed in both academic and private sectors with extensive experience at national and international levels, and has contributed significantly to the development of the environmental health field in Malaysia. His research primarily focuses on the health effects of heavy metals, pesticides, solvents, and air pollution; risk assessment; and, more recently, climate change. His work had garnered 5,622 citations, with an h-index of 40.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (42, 1, 'Professor Dr Sreeramanan Subramaniam', 'School of Biological Sciences, Universiti Sains Malaysia', 'Universiti Sains Malaysia', '/storage/photos/professor-dr-sreeramanan-subramaniam.jpeg', 'Professor Dr Sreeramanan Subramaniam is an expert in plant biotechnology. His research focuses on plant tissue culture, genetic transformation, molecular breeding, cryopreservation, and the development of high-value horticultural crops through sustainable indoor and controlled-environment farming systems using LED technology. His studies on plant genetic engineering and micropropagation of tropical crops contributed significantly to the advancement of plant biotechnology in Malaysia. His publications have a citation count of 5,392 and an h-index of 34.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (43, 2, 'Professor ChM Dr Juan Joon Ching', 'Nanotechnology and Catalysis Research Centre, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-chm-dr-juan-joon-ching.png', 'Professor ChM Dr Juan Joon Ching is recognised for his expertise in nanotechnology and catalysis, particularly in developing nanostructured catalytic materials for sustainable energy and environmental applications. His research focuses on advanced nanomaterials, mesoporous catalysts, and photocatalytic systems to address challenges in renewable fuel production, environmental remediation, and greener chemical processes. His publications garnered over 19,000 citations with an h-index of 62.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (44, 3, 'Dato’ Professor Ir Dr Ahmad Farhan Mohd Sadallah', 'Vice-Chancellor, Universiti Putra Malaysia', 'Universiti Putra Malaysia', '/storage/photos/dato-professor-ir-dr-ahmad-farhan-mohd-sadallah.jpeg', 'Dato’ Professor Ir Dr Ahmad Farhan Mohd Sadallah is a leading expert in transportation engineering, with a focus on road safety. His professional work covers traffic impact assessment, road safety management, and transport planning, demonstrating a comprehensive approach to improving transportation systems and public safety. He contributed to the Traffic Impact Assessment (TIA) in Malaysia by organising the first national TIA training in 1997. He also authored the REAM Manual for TIA, which became the main reference for practitioners until it was adopted by the Board of Engineers Malaysia (BEM). He developed the Malaysian Trip Generation Manual (Versions 2–4) and the Malaysian Highway Capacity Manual, which continue to serve as essential references for practitioners.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (45, 3, 'Professor Ir Dr Ching Yern Chee', 'Faculty of Engineering, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-ir-dr-ching-yern-chee.jpeg', 'Professor Ir Dr Ching Yern Chee is an expert in materials science, with specialisation in polymer nanocomposites, bionanocomposite coatings, biomaterials, functional composites, and nanocellulose-based composites. She garnered a h-index of 50 and more than 9,000 citations. Her work extends to applied research, industrial projects, and consultancies.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (46, 3, 'Professor Ir Dr Faridah Othman', 'Faculty of Engineering, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-ir-dr-faridah-othman.jpeg', 'Professor Ir Dr Faridah Othman is an expert in hydrology, recognised in the environmental aspect of water quality. Her research focuses on water-related challenges, including climate change, urbanisation, water supply, water security, flooding, river conservation, and water pollution. She has an h-index of 32 and a citation count of 3,903. She holds two granted patents related to pipe coating materials and the application of AI in reservoir operation and has been actively involved in 20 consultancy projects.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (47, 3, 'Professor Ts Dr Mohamad Kamal A Rahim', 'Faculty of Electrical Engineering, Universiti Teknologi Malaysia', 'Universiti Teknologi Malaysia', '/storage/photos/professor-ts-dr-mohamad-kamal-a-rahim.jpeg', 'Professor Ts Dr Mohamad Kamal A Rahim is an expert in radio frequency (RF), microwave, and antenna engineering. His work focuses on patch antenna design, reconfigurable antennas, textile antennas, wireless power transfer, metamaterials, metasurfaces, and intelligent surfaces. He achieved an h-index of 49 with 15,819 citations. He has also filed more than 30 patents related to antennas, frequency selective surfaces (FSS), intelligent surfaces, and beamforming networks.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (48, 3, 'Professor Ir Ts Dr Mohamed Thariq Hameed Sultan', 'Faculty of Engineering, Universiti Putra Malaysia', 'Universiti Putra Malaysia', '/storage/photos/professor-ir-ts-dr-mohamed-thariq-hameed-sultan.jpeg', 'Professor Ir Ts Dr Mohamed Thariq Hameed Sultan specialises in structural health monitoring and composite materials, with significant contributions to the development of advanced materials for aerospace and drone technologies. He has an h-index of 70 with more than 16,000 citations.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (49, 3, 'Professor Dr Omar Yaakob', 'Faculty of Mechanical Engineering, Universiti Teknologi Malaysia', 'Universiti Teknologi Malaysia', '/storage/photos/professor-dr-omar-yaakob.jpeg', 'Professor Dr Omar Yaakob is a distinguished expert in marine engineering, with specialisations in ocean engineering, naval architecture, marine environment, and ocean renewable energy. He had made significant contributions to the development of Malaysia’s marine engineering capabilities. His publications record an h-index of 28 and a citation count of 3,100.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (50, 3, 'Professor Ir Ts Dr Sharul Kamal Abdul Rahim', 'Faculty of Electrical Engineering, Universiti Teknologi Malaysia', 'Universiti Teknologi Malaysia', '/storage/photos/professor-ir-ts-dr-sharul-kamal-abdul-rahim.jpeg', 'Professor Ir Ts Dr Sharul Kamal Abdul Rahim is an expert in wireless communication technologies with recognised contributions to both research and industry applications. He has an h-index of 36 with a citation count of 4,981. His work focuses on the design and integration of wireless systems for practical applications, including collaborations with local industries and government agencies.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (51, 3, 'Professor Dr Tang Tong Boon', 'Faculty of Engineering, Universiti Teknologi PETRONAS', 'Universiti Teknologi PETRONAS', '/storage/photos/professor-dr-tang-tong-boon.png', 'Professor Dr Tang Tong Boon is an expert in neurotechnology for mental health and biomedical imaging. He has also been recognised for his work in designing electrical and optical based sensing system (electroencephalography and fNIRS) to detect mental stress objectively. His publications have garnered over 5,500 citations and an h-index of 38.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (52, 3, 'Professor Ir Ts Dr Tiong Sieh Kiong', 'Faculty of Engineering, Universiti Tenaga Nasional', 'Universiti Tenaga Nasional', '/storage/photos/professor-ir-ts-dr-tiong-sieh-kiong.jpeg', 'Professor Ir Ts Dr Tiong Sieh Kiong is a prominent expert in renewable energy technologies, contributing significantly to Malaysia’s energy sector through AI-driven technologies. His research encompasses smart grids, battery energy storage systems, DC microgrids, low-speed wind energy technologies, power systems, renewable energy integration, and green technology innovation. His publications garnered over 9,600 citations and an h-index of 46. His work resulted in 25 intellectual properties, including patents and utility innovations. Notably, his Predictive Emission Monitoring System (T-PEMS) has been commercialised and deployed at power stations with Department of Environment endorsement, delivering tangible revenue and environmental benefits.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (53, 3, 'Professor Ir Dr Vigna Kumaran Ramachandaramurthy', 'Institute of Power Engineering, Universiti Tenaga Nasional', 'Universiti Tenaga Nasional', '/storage/photos/professor-ir-dr-vigna-kumaran-ramachandaramurthy.jpeg', 'Professor Ir Dr Vigna Kumaran Ramachandaramurthy is an expert in electrical power, specialising in renewable energy and smart grid technologies. His publications garnered a citation count of 16,769 and an h-index of 63. He made substantial contributions to Malaysia’s power and renewable energy sector through technical guidelines, strategic planning, and master plans.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (54, 4, 'Professor Ir Dr Hafizal Mohamad', 'Research and Innovation Management Centre, Universiti Sains Islam Malaysia', 'Universiti Sains Islam Malaysia', '/storage/photos/professor-ir-dr-hafizal-mohamad.jpeg', 'Professor Ir Dr Hafizal Mohamad is recognised for his expertise in wireless communications and networking, with particular distinction in next-generation mobile networks and Internet of Things (IoT) systems. His research has advanced key areas, including 5G and emerging 6G technologies, wireless mesh networks, cognitive radio systems, and intelligent network architectures. His scholarly output attracted more than 1,800 citations and an h-index of 22. Beyond academia, his innovations delivered tangible benefits to industry and contributed to Malaysia’s digital transformation.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (55, 4, 'YM Raja Azrina Raja Othman', 'Chief Information Security Officer, Telekom Malaysia', 'Telekom Malaysia', '/storage/photos/ym-raja-azrina-raja-othman.png', 'YM Raja Azrina Raja Othman is an expert in cybersecurity with experience in the areas of security operations and strategic initiatives. She specialises in almost 10 domains of information security, including defence-in-depth design; development and implementation of security architecture (infrastructure and application); digital forensics; cybersecurity risk management and threat modelling; defences against emerging threats; threat intelligence and security testing; cybersecurity incidents & crisis management; and security in AI development.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (56, 5, 'Professor Dr Gan Shiaw Sze @ Gan Gin Gin', 'Faculty of Medicine, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-dr-gan-shiaw-sze-at-gan-gin-gin.jpeg', 'Professor Dr Gan Shiaw Sze @ Gan Gin Gin is an expert in clinical haematology, with specialisation in haematopoietic stem cell transplantation and the management of blood cancers, including lymphoma and multiple myeloma. She has contributed to research in haematological malignancies, transplantation outcomes, and pharmacogenomics, with particular attention to generating clinical and translational evidence relevant to Malaysian and Asian populations. Her publication recorded an h-index of 23 and 1,940 citations. She served as principal investigator in multiple international clinical trials, contributing Malaysian data to regional and global haematology research.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (57, 5, 'Dato’ Dr Mohd Zaki Salleh', 'Chief Executive Officer, Zakesy Biotech Sdn Bhd', 'Zakesy Biotech Sdn Bhd', '/storage/photos/dato-dr-mohd-zaki-salleh.png', 'Dato’ Dr Mohd Zaki Salleh is an expert in precision health, pharmacogenomics, and medical genomics, with expertise in omics-based approaches for healthcare applications. His research covers genomic, metabolomic, and pharmacogenomic studies related to personalised medicine and genomic diagnostics in Malaysian populations. His publications garnered an h-index of 35 with over 4,000 citations. He has registered three patents and developed genetic tests that are widely used in clinical practice. This test enables medical professionals to optimise drug therapies and prevent adverse reactions, representing a major advancement in personalised healthcare. In 2013, he and his team sequenced the first whole genome of a Malay individual and subsequently led the whole genome sequencing of the Orang Asli population. His efforts led to the development of a whole genome sequencing pipeline and a genotype-phenotype database, contributing to Malaysia’s capability in genomic medicine and personalised healthcare.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (58, 6, 'Professor Dr Yong Ken Tye', 'Faculty of Engineering, University of Sydney', 'University of Sydney', '/storage/photos/professor-dr-yong-ken-tye.png', 'Professor Dr Yong Ken Tye is an expert in materials physics, specialising in nanomaterials, nanotechnology, and semiconductor-based sensing systems. His research focuses on the synthesis and characterisation of advanced nanomaterials and their applications in biosensing, bioimaging, and environmental monitoring. Through his work on semiconductor nanocrystals and nanomaterial-based sensing technologies, he contributed significantly to advances in disease detection, biomedical imaging, and environmental sensing. His publications have garnered 28,128 citations, with an h-index of 88.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (59, 8, 'Ms Chee Yoke Ling', 'Executive Director, Third World Network', 'Third World Network', '/storage/photos/ms-chee-yoke-ling.jpeg', 'Ms Chee Yoke Ling is an expert in international law, specialising in global economic governance, sustainable development, intellectual property, and public health. She made significant contributions to national and international law and policy, particularly in promoting public welfare and developmental equity.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (60, 8, 'Professor TPr Dr Goh Hong Ching', 'Faculty of Built Environment, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-tpr-dr-goh-hong-ching.png', 'Professor TPr Dr Goh Hong Ching is known as an interdisciplinary social scientist whose work on human-environment interactions have advanced research, community engagement, and capacity building. Her work integrates environmental conservation, community development, and the green economy, applying participatory approaches that ensure research is relevant and impactful to societal needs. Her research spans tourism planning, urban planning, and human-environment interactions, focusing on sustainability, environmental issues, and community engagement. Her research earned 1,521 citations and an h-index of 22.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (61, 8, 'Madam Hazami Habib', 'Chief Executive Officer, Academy of Sciences Malaysia (ASM)', 'Academy of Sciences Malaysia (ASM)', '/storage/photos/madam-hazami-habib.jpeg', 'Madam Hazami Habib is recognised for her contributions to ASM and to the national Science, Technology, Innovation and Economy (STIE) ecosystem through more than 30 years of dedicated service. Her areas of specialisation include policy development and implementation, talent development, strategic science communication, foresight, science diplomacy, STIE governance, and institution development. She has strengthened ASM’s organisational capacity by developing internal expertise in evidence-based policy analysis and strategic communication, enabling ASM to effectively support Fellows in translating scientific knowledge into policy-relevant outcomes.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (62, 8, 'Professor Dato’ Dr Norzaini Azman', 'Faculty of Education, Universiti Kebangsaan Malaysia', 'Universiti Kebangsaan Malaysia', '/storage/photos/professor-dato-dr-norzaini-azman.png', 'Professor Dato’ Dr Norzaini Azman is a scholar in higher education policy and governance. Her areas of expertise include higher education leadership, academic profession, institutional change, and higher education for sustainability, with particular emphasis on academic leadership development. Her publications garnered a citation count of 3,069 and an h-index of 29.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (63, 8, 'Professor Dr Santha Vaithilingam', 'Deputy Director, Sunway Institute for Global Strategy and Competitiveness, Sunway University', 'Sunway University', '/storage/photos/professor-dr-santha-vaithilingam.png', 'Professor Dr Santha Vaithilingam is recognised for her expertise in econometrics, policy modelling, behavioural science, and Science, Technology, Innovation, and Economic (STIE) policy development. Her work focuses on the application of analytical tools and econometric models to support evidence-based policymaking aligned with national priorities and the United Nations Sustainable Development Goals. She authored more than 90 research papers, research reports, policy briefs, and book chapters, contributing to policy and academic discourse in behavioural economics, econometrics, and technology adoption. Her scholarly work received over 7,000 citations, and she has an h-index of 18.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (64, 8, 'Professor Dr Surinderpal Kaur Chanan Singh', 'Dean, Faculty of Languages and Linguistics, Universiti Malaya', 'Universiti Malaya', '/storage/photos/professor-dr-surinderpal-kaur-chanan-singh.jpeg', 'Professor Dr Surinderpal Kaur Chanan Singh is a respected scholar in critical discourse studies and multimodality, with a focus on discrimination, Islamophobia, extremism, and gender. Her publications recorded an h-index of 12 and a citation count of 548. She is a recognised researcher in Islamophobia, investigating prejudice and discrimination against Muslims. As such, she is often invited to speak and provide insights into the social and political ramifications of anti-Muslim discrimination at high-level international meetings. She is also involved in radicalisation programmes with the Southeast Asia Regional Centre for Counter Terrorism (SEARCCT), under the Ministry of Foreign Affairs of Malaysia, and with the Rabdan Academy in the UAE.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (65, 7, 'Tan Sri Dato’ Seri Professor Ir Ts Dr Abdahir Haji Abdul Majid JP', 'Founder, Jopami Group of Companies', 'Jopami Group of Companies', '/storage/photos/tan-sri-dato-seri-professor-ir-ts-dr-abdahir-haji-abdul-majid-jp.jpeg', 'Tan Sri Dato’ Seri Professor Ir Ts Dr Abdahir Haji Abdul Majid JP is an expert in civil and structural engineering, with extensive experience in the planning and development of major infrastructure projects, including airports, highways and road systems. He is recognised for his industry-based engineering practice and leadership in implementing large-scale infrastructure and development projects in Malaysia.
INSERT INTO "candidates" ("id", "discipline_id", "candidate_name", "candidate_title", "organisation", "photo_url", "basis_of_recommendation", "area_of_expertise", "qualifications", "professional_memberships", "short_description", "nomination_form_url", "display_order", "active", "created_at", "updated_at", "affiliation_to_asm", "qualifications_professional_memberships") VALUES (66, 7, 'Dr Ismail Hashim', 'President, Persatuan Pesara Lembaga Getah Malaysia', 'Persatuan Pesara Lembaga Getah Malaysia', '/storage/photos/dr-ismail-hashim.jpeg', 'Dr Ismail Hashim is an expert in plant science, particularly in agronomy, crop production, and technology development for natural rubber. He has made transformative contributions to agronomy and natural rubber exploitation technologies, including the development of micro-tapping, ethylene-based stimulation systems, ergonomic tapping implements, intercropping techniques, and yield stimulation methods. These innovations boosted farmers'' yields and productivity, resulting in a 40-70% increase in their income.
