CREATE TABLE IF NOT EXISTS "migrations" (
    "id" SERIAL PRIMARY KEY,
    "migration" VARCHAR(255) NOT NULL,
    "batch" INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS "password_reset_tokens" (
    "email" VARCHAR(255) PRIMARY KEY,
    "token" VARCHAR(255) NOT NULL,
    "created_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "sessions" (
    "id" VARCHAR(255) PRIMARY KEY,
    "user_id" BIGINT NULL,
    "ip_address" VARCHAR(45) NULL,
    "user_agent" TEXT NULL,
    "payload" TEXT NOT NULL,
    "last_activity" INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS "sessions_user_id_index" ON "sessions" ("user_id");
CREATE INDEX IF NOT EXISTS "sessions_last_activity_index" ON "sessions" ("last_activity");

CREATE TABLE IF NOT EXISTS "cache" (
    "key" VARCHAR(255) PRIMARY KEY,
    "value" TEXT NOT NULL,
    "expiration" INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS "cache_locks" (
    "key" VARCHAR(255) PRIMARY KEY,
    "owner" VARCHAR(255) NOT NULL,
    "expiration" INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS "jobs" (
    "id" BIGSERIAL PRIMARY KEY,
    "queue" VARCHAR(255) NOT NULL,
    "payload" TEXT NOT NULL,
    "attempts" SMALLINT NOT NULL,
    "reserved_at" INTEGER NULL,
    "available_at" INTEGER NOT NULL,
    "created_at" INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS "jobs_queue_index" ON "jobs" ("queue");

CREATE TABLE IF NOT EXISTS "job_batches" (
    "id" VARCHAR(255) PRIMARY KEY,
    "name" VARCHAR(255) NOT NULL,
    "total_jobs" INTEGER NOT NULL,
    "pending_jobs" INTEGER NOT NULL,
    "failed_jobs" INTEGER NOT NULL,
    "failed_job_ids" TEXT NOT NULL,
    "options" TEXT NULL,
    "cancelled_at" INTEGER NULL,
    "created_at" INTEGER NOT NULL,
    "finished_at" INTEGER NULL
);

CREATE TABLE IF NOT EXISTS "failed_jobs" (
    "id" BIGSERIAL PRIMARY KEY,
    "uuid" VARCHAR(255) UNIQUE NOT NULL,
    "connection" TEXT NOT NULL,
    "queue" TEXT NOT NULL,
    "payload" TEXT NOT NULL,
    "exception" TEXT NOT NULL,
    "failed_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "disciplines" (
    "id" BIGSERIAL PRIMARY KEY,
    "discipline_name" VARCHAR(255) NOT NULL,
    "description" TEXT NULL,
    "display_order" INTEGER DEFAULT 0,
    "active" BOOLEAN DEFAULT TRUE,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "users" (
    "id" BIGSERIAL PRIMARY KEY,
    "name" VARCHAR(255) NOT NULL,
    "email" VARCHAR(255) NOT NULL,
    "email_verified_at" TIMESTAMP NULL,
    "password" VARCHAR(255) NOT NULL,
    "remember_token" VARCHAR(100) NULL,
    "role" VARCHAR(50) DEFAULT 'voting_user',
    "discipline_id" BIGINT NULL REFERENCES "disciplines"("id") ON DELETE SET NULL,
    "active" BOOLEAN DEFAULT TRUE,
    "last_login" TIMESTAMP NULL,
    "username" VARCHAR(255) NULL,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);
CREATE INDEX IF NOT EXISTS "users_email_index" ON "users" ("email");
CREATE INDEX IF NOT EXISTS "users_discipline_id_index" ON "users" ("discipline_id");

CREATE TABLE IF NOT EXISTS "ranking_exercises" (
    "id" BIGSERIAL PRIMARY KEY,
    "exercise_name" VARCHAR(255) NOT NULL,
    "description" TEXT NULL,
    "start_datetime" TIMESTAMP NULL,
    "end_datetime" TIMESTAMP NULL,
    "status" VARCHAR(50) DEFAULT 'Draft',
    "allow_resubmission" BOOLEAN DEFAULT FALSE,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "candidates" (
    "id" BIGSERIAL PRIMARY KEY,
    "discipline_id" BIGINT NOT NULL REFERENCES "disciplines"("id") ON DELETE CASCADE,
    "candidate_name" VARCHAR(255) NOT NULL,
    "candidate_title" VARCHAR(255) NULL,
    "organisation" VARCHAR(255) NULL,
    "photo_url" VARCHAR(255) NULL,
    "affiliation_to_asm" TEXT NULL,
    "basis_of_recommendation" TEXT NULL,
    "area_of_expertise" TEXT NULL,
    "qualifications" TEXT NULL,
    "professional_memberships" TEXT NULL,
    "qualifications_professional_memberships" TEXT NULL,
    "short_description" TEXT NULL,
    "nomination_form_url" TEXT NULL,
    "display_order" INTEGER DEFAULT 0,
    "active" BOOLEAN DEFAULT TRUE,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);
CREATE INDEX IF NOT EXISTS "candidates_discipline_id_index" ON "candidates" ("discipline_id");

CREATE TABLE IF NOT EXISTS "ranking_submissions" (
    "id" BIGSERIAL PRIMARY KEY,
    "user_id" BIGINT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
    "exercise_id" BIGINT NOT NULL REFERENCES "ranking_exercises"("id") ON DELETE CASCADE,
    "discipline_id" BIGINT NOT NULL REFERENCES "disciplines"("id") ON DELETE CASCADE,
    "status" VARCHAR(50) DEFAULT 'DRAFT',
    "submitted_at" TIMESTAMP NULL,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);
CREATE INDEX IF NOT EXISTS "ranking_submissions_user_exercise_index" ON "ranking_submissions" ("user_id", "exercise_id");

CREATE TABLE IF NOT EXISTS "rankings" (
    "id" BIGSERIAL PRIMARY KEY,
    "submission_id" BIGINT NOT NULL REFERENCES "ranking_submissions"("id") ON DELETE CASCADE,
    "user_id" BIGINT NULL REFERENCES "users"("id") ON DELETE SET NULL,
    "exercise_id" BIGINT NULL REFERENCES "ranking_exercises"("id") ON DELETE CASCADE,
    "discipline_id" BIGINT NULL REFERENCES "disciplines"("id") ON DELETE CASCADE,
    "candidate_id" BIGINT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,
    "ranking_number" INTEGER NOT NULL,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);
CREATE INDEX IF NOT EXISTS "rankings_submission_id_index" ON "rankings" ("submission_id");

CREATE TABLE IF NOT EXISTS "due_diligence_categories" (
    "id" BIGSERIAL PRIMARY KEY,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT NULL,
    "display_order" INTEGER DEFAULT 0,
    "active" BOOLEAN DEFAULT TRUE,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "due_diligence_submissions" (
    "id" BIGSERIAL PRIMARY KEY,
    "user_id" BIGINT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
    "candidate_id" BIGINT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,
    "category_id" BIGINT NOT NULL REFERENCES "due_diligence_categories"("id") ON DELETE CASCADE,
    "comment" TEXT NOT NULL,
    "user_discipline_id" BIGINT NULL REFERENCES "disciplines"("id") ON DELETE SET NULL,
    "reference_1_name" VARCHAR(255) NULL,
    "reference_1_designation" VARCHAR(255) NULL,
    "reference_1_organisation" VARCHAR(255) NULL,
    "reference_1_contact_number" VARCHAR(255) NULL,
    "reference_1_email" VARCHAR(255) NULL,
    "reference_2_name" VARCHAR(255) NULL,
    "reference_2_designation" VARCHAR(255) NULL,
    "reference_2_organisation" VARCHAR(255) NULL,
    "reference_2_contact_number" VARCHAR(255) NULL,
    "reference_2_email" VARCHAR(255) NULL,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "supporting_documents" (
    "id" BIGSERIAL PRIMARY KEY,
    "due_diligence_submission_id" BIGINT NULL REFERENCES "due_diligence_submissions"("id") ON DELETE CASCADE,
    "original_filename" VARCHAR(255) NOT NULL,
    "stored_filename" VARCHAR(255) NOT NULL,
    "storage_path" VARCHAR(255) NOT NULL,
    "mime_type" VARCHAR(100) NOT NULL,
    "file_size" INTEGER NOT NULL,
    "created_at" TIMESTAMP NULL,
    "updated_at" TIMESTAMP NULL
);

CREATE TABLE IF NOT EXISTS "audit_logs" (
    "id" BIGSERIAL PRIMARY KEY,
    "user_id" BIGINT NULL REFERENCES "users"("id") ON DELETE SET NULL,
    "action" VARCHAR(255) NOT NULL,
    "record_type" VARCHAR(255) NULL,
    "record_id" BIGINT NULL,
    "description" TEXT NULL,
    "ip_address" VARCHAR(45) NULL,
    "user_agent" TEXT NULL,
    "created_at" TIMESTAMP NULL
);

